#Requires -Version 7.0
$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest
$run = Join-Path ([IO.Path]::GetTempPath()) ('luckyray-webview2-' + [guid]::NewGuid().ToString('N'))
$out = Join-Path $PSScriptRoot '../output/webview2'
# This fixed directory is exclusively generated by this QA lane. Never mix prior evidence.
if (Test-Path $out) { Remove-Item -LiteralPath $out -Recurse -Force }
New-Item -ItemType Directory -Force $run, $out | Out-Null
$owned = @()
$hostProcess = $null
$port = $null
$exit = 1
$cleanupFailed = $false
function Start-Owned([string]$exe, [string[]]$arguments, [string]$name) {
    $p = Start-Process -FilePath $exe -ArgumentList $arguments -PassThru -RedirectStandardOutput (Join-Path $run "$name.stdout.log") -RedirectStandardError (Join-Path $run "$name.stderr.log")
    $script:owned += [pscustomobject]@{ Process = $p; Started = $p.StartTime.ToUniversalTime(); Path = $p.Path }
    return $p
}
function Remember-Descendants($root) {
    $root.Refresh()
    if ($root.HasExited) { return }
    $known = @{}; foreach ($entry in $script:owned) { $known[$entry.Process.Id] = $true }
    $parents = @($root.Id)
    $all = @(Get-CimInstance Win32_Process)
    while ($parents.Count) {
        $children = @($all | Where-Object { $_.ParentProcessId -in $parents })
        $parents = @()
        foreach ($child in $children) {
            if ($known.ContainsKey([int]$child.ProcessId)) { $parents += [int]$child.ProcessId; continue }
            $p = Get-Process -Id $child.ProcessId -ErrorAction SilentlyContinue
            if ($p -and $p.StartTime.ToUniversalTime() -ge $root.StartTime.ToUniversalTime()) {
                $script:owned += [pscustomobject]@{ Process=$p; Started=$p.StartTime.ToUniversalTime(); Path=$p.Path }
                $known[$p.Id]=$true; $parents += $p.Id
            }
        }
    }
}
function Wait-File([string]$file, $process) {
    $deadline = (Get-Date).AddSeconds(45)
    while (!(Test-Path $file)) {
        Remember-Descendants $process
        $process.Refresh()
        if ($process.HasExited) { throw "Process exited before $file (exit $($process.ExitCode)); inspect native.jsonl" }
        if ((Get-Date) -gt $deadline) { throw "Timed out waiting for $file" }
        Start-Sleep -Milliseconds 100
    }
}
function Verify-Listener($ready) {
    Remember-Descendants $hostProcess
    $listeners = @(Get-NetTCPConnection -State Listen -LocalPort $ready.debugPort -ErrorAction SilentlyContinue)
    if ($listeners.Count -eq 0) { throw 'No CDP listener' }
    foreach ($listener in $listeners) {
        if ($listener.LocalAddress -notin @('127.0.0.1','::1') -or $listener.OwningProcess -ne $ready.browserProcessId) { throw 'Unsafe or unrelated CDP listener; stopping owned process tree' }
    }
    # The runtime process must descend from the exact host launched by this script.
    $id = [int]$ready.browserProcessId
    $seen = @{}
    while ($id -ne $hostProcess.Id) {
        if ($id -le 0 -or $seen.ContainsKey($id)) { throw 'CDP process is not owned by this host' }
        $seen[$id] = $true
        $item = Get-CimInstance Win32_Process -Filter "ProcessId=$id"
        if (!$item) { throw 'Runtime process disappeared' }
        $id = [int]$item.ParentProcessId
    }
}
try {
    Push-Location $PSScriptRoot
    try {
        & dotnet --info | Out-File (Join-Path $run 'dotnet-info.log')
        if ($LASTEXITCODE -ne 0) { throw 'Required .NET SDK unavailable' }
        & dotnet restore Host/Host.csproj --locked-mode --configfile NuGet.Config
        if ($LASTEXITCODE -ne 0) { throw 'Locked official NuGet restore failed' }
        & dotnet build Host/Host.csproj -c Release --no-restore
        if ($LASTEXITCODE -ne 0) { throw 'Host build failed' }
    } finally { Pop-Location }
    $node = (Get-Command node).Source
    $server = Start-Owned $node @(('"' + (Join-Path $PSScriptRoot 'server.cjs') + '"'), ('"' + $run + '"')) 'server'
    Wait-File (Join-Path $run 'server.json') $server
    $url = (Get-Content (Join-Path $run 'server.json') -Raw | ConvertFrom-Json).url
    $socket = [Net.Sockets.TcpListener]::new([Net.IPAddress]::Loopback, 0)
    $socket.Start(); $port = $socket.LocalEndpoint.Port; $socket.Stop()
    $hostExe = Join-Path $PSScriptRoot 'Host/bin/Release/net8.0-windows/Host.exe'
    $hostProcess = Start-Owned $hostExe @(('"' + $run + '"'), $url, "$port") 'host'
    Wait-File (Join-Path $run 'ready.json') $hostProcess
    $ready = Get-Content (Join-Path $run 'ready.json') -Raw | ConvertFrom-Json
    if ($ready.hostProcessId -ne $hostProcess.Id -or $ready.debugPort -ne $port -or $ready.url -ne $url) { throw 'Host handshake mismatch' }
    Verify-Listener $ready
    @{ port=$port; browserProcessId=$ready.browserProcessId; checkedAt=(Get-Date).ToUniversalTime().ToString('o') } | ConvertTo-Json | Set-Content (Join-Path $run 'listener-verified.json')
    $test = Start-Owned $node @(('"' + (Join-Path $PSScriptRoot 'test.cjs') + '"'), ('"' + $run + '"')) 'test'
    $deadline = (Get-Date).AddMinutes(5)
    while (!$test.HasExited) {
        $hostProcess.Refresh(); if ($hostProcess.HasExited) { throw 'Native host exited during tests' }
        Verify-Listener $ready
        if ((Get-Date) -gt $deadline) { throw 'WebView2 test timeout' }
        Start-Sleep -Milliseconds 250; $test.Refresh()
    }
    if ($test.ExitCode -ne 0) { throw "Browser tests failed: $($test.ExitCode)" }
    $native = @(Get-Content (Join-Path $run 'native.jsonl') | ForEach-Object { $_ | ConvertFrom-Json })
    if (@($native | Where-Object { $_.type -notin @('environment','navigation','resize') }).Count) { throw 'Native host recorded errors' }
    if (!(Test-Path (Join-Path $run 'browser-result.json')) -or (Get-Content (Join-Path $run 'browser-result.json') -Raw | ConvertFrom-Json).status -ne 'PASS') { throw 'Missing PASS result' }
    @{status='PASS'; runtime=$ready.browserVersion; scope='Synthetic native WebView2 UI only; not Tauri/LSH acceptance'} | ConvertTo-Json | Set-Content (Join-Path $run 'result.json')
    $exit = 0
} catch {
    $status = 'FAIL'
    if ((Test-Path (Join-Path $run 'native.jsonl')) -and (Select-String -Path (Join-Path $run 'native.jsonl') -Pattern 'BLOCKED_RUNTIME_MISSING' -Quiet)) { $status = 'BLOCKED_RUNTIME_MISSING' }
    @{status=$status; error=$_.ToString()} | ConvertTo-Json | Set-Content (Join-Path $run 'result.json')
    Write-Error $_ -ErrorAction Continue
} finally {
    if ($hostProcess -and !$hostProcess.HasExited) {
        try {
            Remember-Descendants $hostProcess
            '{"action":"close"}' | Set-Content (Join-Path $run 'command.json') -Encoding utf8
            $null = $hostProcess.WaitForExit(3000)
        } catch { Write-Warning 'Graceful host close failed; owned-process cleanup follows' }
    }
    # Only processes created here, still matching start time and executable, are eligible.
    foreach ($entry in ($owned | Sort-Object Started -Descending)) {
        try {
            $p = Get-Process -Id $entry.Process.Id -ErrorAction SilentlyContinue
            if ($p -and $p.StartTime.ToUniversalTime() -eq $entry.Started -and $p.Path -eq $entry.Path) {
                & taskkill /PID $p.Id /T /F | Out-Null
                if (!$p.WaitForExit(3000)) { $cleanupFailed=$true }
            }
        } catch { $cleanupFailed=$true; Write-Warning "Owned process cleanup failed: $_" }
    }
    if ($port -and @(Get-NetTCPConnection -State Listen -LocalPort $port -ErrorAction SilentlyContinue).Count) { $cleanupFailed=$true }
    if (Test-Path (Join-Path $run 'native.jsonl')) {
        $lateNative = @(Get-Content (Join-Path $run 'native.jsonl') | ForEach-Object { $_ | ConvertFrom-Json })
        if ($exit -eq 0 -and @($lateNative | Where-Object { $_.type -notin @('environment','navigation','resize') }).Count) {
            $exit=1
            @{status='FAIL';error='Late native error during shutdown; inspect native.jsonl'} | ConvertTo-Json | Set-Content (Join-Path $run 'result.json')
        }
    }
    if ($cleanupFailed) {
        $exit=1
        @{status='FAIL_CLEANUP'; error='At least one owned process could not be verified stopped'} | ConvertTo-Json | Set-Content (Join-Path $run 'result.json')
    }
    Get-ChildItem $run -File | Where-Object { $_.Extension -in @('.json','.jsonl','.png','.zip','.log') } | Copy-Item -Destination $out -Force
    try { Remove-Item -LiteralPath $run -Recurse -Force } catch { $exit=1; @{status='FAIL_CLEANUP';error='Temporary QA directory could not be fully removed'} | ConvertTo-Json | Set-Content (Join-Path $out 'result.json'); Write-Warning 'Temporary QA directory could not be fully removed' }
}
exit $exit
